<?php
require_once __DIR__.'/includes/db.php';if(current_user()){header('Location: index.php');exit;}$err='';if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$n=trim($_POST['name']??'');$em=strtolower(trim($_POST['email']??''));$pw=$_POST['password']??'';if(mb_strlen($n)<2||!filter_var($em,FILTER_VALIDATE_EMAIL)||strlen($pw)<10)$err='Tên/email không hợp lệ hoặc mật khẩu dưới 10 ký tự.';else{try{$s=db()->prepare("INSERT INTO users(name,email,password_hash) VALUES(?,?,?)");$s->execute([$n,$em,password_hash($pw,PASSWORD_DEFAULT)]);flash('Đăng ký thành công. Mời đăng nhập.');header('Location: login.php');exit;}catch(PDOException $x){$err='Email đã được sử dụng.';}}}$pageTitle='Đăng ký';require __DIR__.'/includes/header.php';?><div class="formbox"><h1>Tạo tài khoản</h1><p class="error"><?=e($err)?></p><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><label>Họ tên</label><input name="name" required><label>Email</label><input type="email" name="email" required><label>Mật khẩu (10 ký tự trở lên)</label><input type="password" name="password" minlength="10" required><button class="btn">Đăng ký</button></form></div></main></body></html>